import Foundation
import GlideCore

// Multiple displays (PROTOCOL.md §3.5): shared vectors (docs/display-vectors.json, generated by
// tools/mock_host.py --display-vectors), identity matching and the host's display resolution.

private struct DisplayVectors: Decodable {
    struct Msg: Decodable { let name: String; let hex: String }
    struct Entry: Decodable {
        let id: UInt32, flags: UInt8, x: Int32, y: Int32, width: UInt16, height: UInt16
        let pixel_width: UInt16, pixel_height: UInt16, refresh: UInt16, vendor: UInt32, model: UInt32, serial: UInt32, name: String
        var descriptor: DisplayDescriptor {
            DisplayDescriptor(id: id, flags: flags, x: x, y: y, width: width, height: height, pixelWidth: pixel_width, pixelHeight: pixel_height,
                              refresh: refresh, vendor: vendor, model: model, serial: serial, name: name)
        }
    }
    struct Ident: Decodable { let id: UInt32, vendor: UInt32, model: UInt32, serial: UInt32, name: String }
    struct Match: Decodable { let what: String; let want: Ident; let expect: UInt32? }
    let messages: [Msg]
    let match_list: [Entry]
    let match: [Match]
}

func displayTests(vectorsDir: URL) throws {
    print("multiple displays (§3.5):")
    let v = try JSONDecoder().decode(DisplayVectors.self, from: Data(contentsOf: vectorsDir.appendingPathComponent("display-vectors.json")))
    let list = v.match_list.map(\.descriptor)
    func d(_ id: UInt32) -> DisplayDescriptor { list.first { $0.id == id }! }
    let builtin = d(1), dellA = d(5), dellB = d(6), virtual = d(9)
    let unicode = DisplayDescriptor(id: 11, flags: 9, x: -1, y: -2, width: 1, height: 2, pixelWidth: 3, pixelHeight: 4, refresh: 0,
                                    vendor: 1, model: 2, serial: 3, name: "Écran 日本")
    let host: [String: HostMessage] = [
        "DisplayChanged": .displayChanged(id: 2, reason: DisplayChangeReason.fallback.rawValue, requested: 5),
        "DisplayChangedUnavailable": .displayChanged(id: 1, reason: DisplayChangeReason.unavailable.rawValue, requested: 0xDEAD_BEEF),
        "DisplayListBuiltin": .displayList(streamed: 1, selected: 0, displays: [builtin]),
        "DisplayList": .displayList(streamed: 5, selected: 5, displays: [builtin, virtual, dellA, dellB]),
        "DisplayListEmpty": .displayList(streamed: 3, selected: 0, displays: []),
        "DisplayListUnicode": .displayList(streamed: 11, selected: 11, displays: [unicode]),
    ]
    let client: [String: ClientMessage] = ["SelectDisplay": .selectDisplay(id: 2), "SelectDisplayAutomatic": .selectDisplay(id: 0)]
    check(host.count + client.count == v.messages.count, "display vectors: one case per reference message")
    for m in v.messages {
        guard let want = Data(hex: m.hex) else { check(false, "display vector \(m.name) hex"); continue }
        if let h = host[m.name] {
            var ok = h.encoded == want
            if let back = try? HostMessage.decode(want) { ok = ok && back.encoded == want } else { ok = false }
            check(ok, "\(m.name) reference bytes + roundtrip")
            check((1..<want.count).allSatisfy { (try? HostMessage.decode(want.prefix($0))) == nil }, "\(m.name) truncation rejected")
        } else if let c = client[m.name] {
            var ok = c.encoded == want
            if case let .selectDisplay(id)? = try? ClientMessage.decode(want), case let .selectDisplay(id0) = c { ok = ok && id == id0 } else { ok = false }
            check(ok, "\(m.name) reference bytes + roundtrip")
            check((1..<want.count).allSatisfy { (try? ClientMessage.decode(want.prefix($0))) == nil }, "\(m.name) truncation rejected")
        } else { check(false, "display vector \(m.name) known") }
    }
    if case let .displayList(_, _, ds)? = try? HostMessage.decode(Data(hex: v.messages.first { $0.name == "DisplayListUnicode" }!.hex)!) {
        check(ds == [unicode], "DisplayList decodes negative positions and UTF-8 names")
    } else { check(false, "DisplayList decode") }

    var bad: [String] = []
    for m in v.match {
        let want = DisplayIdentity(id: m.want.id, vendor: m.want.vendor, model: m.want.model, serial: m.want.serial, name: m.want.name)
        let got = want.match(in: list)
        if got != m.expect { bad.append("\(m.what): got \(got.map(String.init) ?? "nil"), want \(m.expect.map(String.init) ?? "nil")") }
    }
    check(bad.isEmpty, "\(v.match.count) identity matching vectors \(bad)")

    // Resolution: selection (by identity) > pinned (while listed) > main.
    let main: UInt32 = 1
    check(DisplaySelection.resolve(selection: nil, pinned: nil, main: main, displays: list) == 1, "resolve: nothing selected -> main")
    check(DisplaySelection.resolve(selection: nil, pinned: 6, main: main, displays: list) == 6, "resolve: --display pin while online")
    check(DisplaySelection.resolve(selection: nil, pinned: 60, main: main, displays: list) == 1, "resolve: offline pin -> main")
    check(DisplaySelection.resolve(selection: dellA.identity, pinned: 6, main: main, displays: list) == 5, "resolve: selection beats pin")
    let unplugged = list.filter { $0.id != 5 }
    check(DisplaySelection.resolve(selection: dellA.identity, pinned: nil, main: main, displays: unplugged) == 1, "resolve: selected display unplugged -> main")
    check(DisplaySelection.resolve(selection: dellA.identity, pinned: 6, main: main, displays: unplugged) == 6, "resolve: selected display unplugged -> pin")
    var replugged = unplugged; var back = dellA; back.id = 77; replugged.append(back)
    check(DisplaySelection.resolve(selection: dellA.identity, pinned: nil, main: main, displays: replugged) == 77, "resolve: re-plugged under a new id -> followed")
    check(DisplaySelection.resolve(selection: dellA.identity, pinned: nil, main: 3, displays: []) == 3, "resolve: empty list (all asleep) -> main")
    check(DisplaySelection.defaultDisplay(pinned: 6, main: main, displays: list) == 6, "default display = pin while listed")

    // Why an unrequested switch happened.
    check(DisplaySelection.unrequestedReason(selection: nil, now: 2, displays: list) == .defaultChanged, "reason: no selection -> default changed")
    check(DisplaySelection.unrequestedReason(selection: dellA.identity, now: 1, displays: unplugged) == .fallback, "reason: selection gone -> fallback")
    check(DisplaySelection.unrequestedReason(selection: dellA.identity, now: 77, displays: replugged) == .restored, "reason: selection back -> restored")

    // List order: left to right, then top to bottom, capped at 32.
    let order = DisplaySelection.ordered([dellB, virtual, dellA, builtin]).map(\.id)
    check(order == [1, 9, 5, 6], "list order x, y, id \(order)")
    let many = (0..<40).map { DisplayDescriptor(id: UInt32(100 - $0), x: Int32($0 % 3), width: 1, height: 1, pixelWidth: 1, pixelHeight: 1, name: "d") }
    check(DisplaySelection.ordered(many).count == DisplayDescriptor.listMax, "list capped at \(DisplayDescriptor.listMax)")
    check(CodecCaps.displays.rawValue == 0x2000, "caps bit 13 = DISPLAYS")
    check(dellB.summary == "DELL U2723QE — 2560×1440 @ 59.94 Hz" && virtual.summary == "Glide Virtual Display — 1920×1080 HiDPI @ 60 Hz", "display summary \(dellB.summary)")
    check(DisplayChangeReason.allCases.map(\.rawValue) == [0, 1, 2, 3, 4, 5], "DisplayChanged reason values")
}
